/* ===================== BÀI 60 · Bảo vệ và chuyển giao ===================== */
/* Bài 60 · Bảo vệ và chuyển giao (AMTS-EMB-001-M15-L04, MC51-060) — sinh bởi tools/author/mcu8051/l60.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P60=[{"label":"Ví dụ: Tổng kiểm của bản build","code":"; Tổng kiểm của bản build: cộng 16 bit mọi byte mã từ 0000H\n; tới trước nhãn HET, ghi vào hồ sơ chuyển giao (30H:31H).\n        ORG     0000H\n        MOV     DPTR,#0000H\n        MOV     R2,#0                   ; byte cao của tổng\n        MOV     R3,#0                   ; byte thấp của tổng\nLAP:    CLR     A\n        MOVC    A,@A+DPTR               ; byte mã thứ DPTR\n        ADD     A,R3\n        MOV     R3,A\n        CLR     A\n        ADDC    A,R2                    ; cộng số nhớ vào byte cao\n        MOV     R2,A\n        INC     DPTR\n        MOV     A,DPL\n        CJNE    A,#HET,LAP              ; chương trình ngắn: HET < 100H\n        MOV     30H,R2\n        MOV     31H,R3\n        SJMP    $\nHET:\n        END\n","note":"26 byte mã từ 0000H tới trước HET (001AH). Mỗi vòng: MOVC đọc một byte, ADD vào R3, ADDC số nhớ vào R2. Đoán trước: vòng chạy mấy lần? (26 lần, mỗi lần 13 chu kỳ: 4 + 26 × 13 + 4 = 346.) Tổng = 0CF9H (3 321), ghi vào hồ sơ. Sửa một byte bất kỳ (ví dụ đổi 30H thành 32H) thì tổng đổi.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Yêu cầu mới — thạch anh 11,0592 MHz","code":"; Yêu cầu mới: đổi thạch anh sang 11,0592 MHz (để UART chạy\n; 9 600 baud đúng). Tick 1 ms = 921,6 chu kỳ → làm tròn 922.\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TH0,#0FCH               ; 65536 − 922 = 64614 = FC66H\n        MOV     TL0,#66H\n        SETB    TR0\nCHO:    JNB     TF0,CHO\n        CLR     TR0\n        CLR     TF0\n        SJMP    $\n        END\n","note":"Thạch anh 11,0592 MHz, nạp FC66H = 65 536 − 922. Đoán trước: tới SJMP $ hết bao nhiêu chu kỳ và bao nhiêu µs? (7 + 922 + 2 = 931 chu kỳ × 12 / 11,0592 MHz ≈ 1 010,2 µs; riêng phần timer 922 chu kỳ ≈ 1 000,43 µs.)","dev":{"led":true},"fosc":11059200},{"label":"Bẫy: Đổi thạch anh, giữ giá trị nạp cũ","code":"; Bẫy: đổi thạch anh sang 11,0592 MHz nhưng giữ giá trị nạp\n; cũ FC18H (tính cho 12 MHz).\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TH0,#0FCH               ; FC18H: 1 000 chu kỳ\n        MOV     TL0,#18H\n        SETB    TR0\nCHO:    JNB     TF0,CHO\n        CLR     TR0\n        CLR     TF0\n        SJMP    $\n        END\n","note":"Cùng chương trình nhưng nạp FC18H tính cho 12 MHz. Timer vẫn đếm 1 000 chu kỳ, nhưng mỗi chu kỳ giờ dài 1,085 µs: 1 009 chu kỳ ≈ 1 094,8 µs. Đoán trước: sau 1 000 tick, đồng hồ của sản phẩm chậm bao nhiêu? (Khoảng 85 ms mỗi giây danh nghĩa, 8,5 %.)","dev":{"led":true},"fosc":11059200},{"label":"Ví dụ: Yêu cầu mới — thêm trạng thái BÁO SỚM","code":"; Yêu cầu mới: thêm trạng thái BÁO SỚM khi số đếm ≥ 90 %\n; hạn mức. TT: 0 CHỜ, 1 ĐẾM, 2 SỚM, 3 BÁO.\n; SK: 0 có SP, 1 đủ hạn mức, 2 xóa, 3 gần đủ (≥ 90 %).\n        ORG     0000H\n        MOV     R5,#0                   ; trạng thái đầu: CHỜ\n        MOV     R4,#0                   ; chỉ số trong kịch bản\n        MOV     R1,#40H                 ; vết trạng thái từ 40H\nVONG:   MOV     DPTR,#SUKIEN\n        MOV     A,R4\n        MOVC    A,@A+DPTR\n        CJNE    A,#0FFH,BUOC            ; FFH = hết kịch bản\n        SJMP    XONG\nBUOC:   MOV     R6,A\n        MOV     A,R5\n        RL      A\n        RL      A                       ; 4 × trạng thái (hàng 4 ô)\n        ADD     A,R6\n        MOV     DPTR,#NEXT\n        MOVC    A,@A+DPTR\n        MOV     R5,A\n        MOV     @R1,A\n        INC     R1\n        INC     R4\n        SJMP    VONG\nXONG:   MOV     30H,R5\n        SJMP    $\nNEXT:   DB      1,0,0,0                 ; từ CHỜ (SK 0, 1, 2, 3)\n        DB      1,3,0,2                 ; từ ĐẾM\n        DB      2,3,0,2                 ; từ SỚM\n        DB      3,3,0,3                 ; từ BÁO (hàng mới)\nSUKIEN: DB      0,3,0,1,0,2,0FFH\n        END\n","note":"Bảng 4 × 4: thêm hàng BÁO (3) và cột “gần đủ” (3, ô trống sẵn có từ Bài 57). Kịch bản SP, gần đủ, SP, đủ, SP, xóa → vết 01, 02, 02, 03, 03, 00. Đoán trước: sau “gần đủ” rồi “có SP”, trạng thái là gì? (2: vẫn SỚM.) Tổng 146 chu kỳ, mỗi sự kiện 22 chu kỳ — bằng Bài 57 vì chỉ số vẫn là 4 × TT + SK.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Mã cho AT89S52 chạy trên 8051 gốc","code":"; Đọc biến thể: bộ đệm đặt ở RAM cao 80H–87H (chỉ có trên\n; 8052/AT89S52). Ví dụ này chạy ở cấu hình 8051 gốc (128 byte).\n        ORG     0000H\n        MOV     30H,#0                  ; cờ \"đã ghi xong\"\n        MOV     R0,#80H                 ; bộ đệm ở RAM cao\n        MOV     @R0,#'C'                ; 8051 gốc: không có ô này!\n        INC     R0\n        MOV     @R0,#'='\n        MOV     30H,#1\n        SJMP    $\n        END\n","note":"MOV R0,#80H rồi MOV @R0,#'C'. Trên AT89S52 ô 80H là RAM cao. Ở cấu hình 8051 gốc (128 byte), trình mô phỏng dừng ở PC = 0005H sau 3 chu kỳ và báo không có vùng 80H–FFH gián tiếp. Chip 8051 thật không báo gì, dữ liệu chỉ mất. Đoán trước: 30H lúc dừng bằng mấy? (00H: chưa tới lệnh MOV 30H,#1.)","dev":{"led":true},"fosc":12000000,"ram":128}];
const sim60=makeSim51(document.getElementById("m51-l60"),{id:"s60",presets:P60,ram:256});
makeEx51(document.getElementById("ex-l60"),"l60",[{"t":"Tính lại giá trị nạp khi đổi thạch anh","d":"<p>Yêu cầu mới đổi thạch anh nên phải tính lại giá trị nạp của Timer chế độ 1. Ô <code>30H<\/code> (byte cao) và <code>31H<\/code> (byte thấp) chứa số chu kỳ máy N cần đếm (1–65535). Ghi giá trị nạp 65536 − N vào <code>32H<\/code> (cho TH) và <code>33H<\/code> (cho TL). Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: N = 1000 = 03E8H → <code>32H = FCH<\/code>, <code>33H = 18H<\/code>; N = 922 (tick 1 ms ở 11,0592 MHz) → FC66H.<\/p>","start":"        ORG     0000H\n        CLR     C\n        CLR     A\n        SUBB    A,31H                   ; byte thấp: 0 − N thấp\n        MOV     33H,A\n; Viết thêm: byte cao vào 32H\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":232,"0x32":238,"0x33":238}},"expect":{"iram":{"0x32":252,"0x33":24}}},{"setup":{"iram":{"0x30":3,"0x31":154,"0x32":238,"0x33":238},"regs":{"PSW":128}},"expect":{"iram":{"0x32":252,"0x33":102}}},{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":238,"0x33":238}},"expect":{"iram":{"0x32":255,"0x33":255}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":238,"0x33":238}},"expect":{"iram":{"0x32":0,"0x33":1}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x32":255,"0x33":0}}},{"setup":{"iram":{"0x30":0,"0x31":255,"0x32":238,"0x33":238}},"expect":{"iram":{"0x32":255,"0x33":1}}},{"setup":{"iram":{"0x30":195,"0x31":80,"0x32":238,"0x33":238}},"expect":{"iram":{"0x32":60,"0x33":176}}}]},"hints":["65536 − N với kết quả 16 bit chính là 0 − N (bỏ số mượn cuối): trừ 16 bit từ 0000H.","Byte thấp: CLR C, CLR A, SUBB A,31H. Cờ C lúc này là số mượn sang byte cao.","Cờ C sau byte thấp là số mượn cho byte cao: đừng làm mất nó (bộ thử 5)."],"why":"Đổi thạch anh là thay đổi yêu cầu điển hình: mọi giá trị nạp timer và baud phải tính lại và ghi vào hồ sơ. Phép trừ 16 bit phải truyền số mượn: bộ thử 5 (0100H) và 6 (00FFH) bắt lỗi xóa C giữa hai byte hoặc quên byte cao."},{"t":"Cảnh báo hai mức","d":"<p>Yêu cầu mới: ngoài cảnh báo khi đủ hạn mức, thêm mức “báo sớm”. Số đếm 16 bit ở <code>30H<\/code>:<code>31H<\/code> (cao:thấp), ngưỡng báo sớm L1 ở <code>32H<\/code>:<code>33H<\/code>, hạn mức L2 ở <code>34H<\/code>:<code>35H<\/code> (L1 ≤ L2). Ghi vào <code>36H<\/code>: <code>00H<\/code> nếu số đếm &lt; L1, <code>01H<\/code> nếu L1 ≤ số đếm &lt; L2, <code>02H<\/code> nếu số đếm ≥ L2. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: số đếm 950, L1 = 900, L2 = 1000 → <code>36H = 01H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     36H,#0                  ; mức 0: dưới L1\n        CLR     C                       ; số đếm − L1 (16 bit)\n        MOV     A,31H\n        SUBB    A,33H\n        MOV     A,30H\n        SUBB    A,32H\n        JC      XONG                    ; số đếm < L1\n        MOV     36H,#1\n; Viết thêm: số đếm ≥ L2 (34H:35H) thì mức 2\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":182,"0x32":3,"0x33":132,"0x34":3,"0x35":232,"0x36":238}},"expect":{"iram":{"0x36":1}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":3,"0x33":132,"0x34":3,"0x35":232,"0x36":238}},"expect":{"iram":{"0x36":0}}},{"setup":{"iram":{"0x30":3,"0x31":132,"0x32":3,"0x33":132,"0x34":3,"0x35":232,"0x36":238},"regs":{"PSW":128}},"expect":{"iram":{"0x36":1}}},{"setup":{"iram":{"0x30":3,"0x31":232,"0x32":3,"0x33":132,"0x34":3,"0x35":232,"0x36":238}},"expect":{"iram":{"0x36":2}}},{"setup":{"iram":{"0x30":39,"0x31":15,"0x32":3,"0x33":132,"0x34":3,"0x35":232,"0x36":238}},"expect":{"iram":{"0x36":2}}},{"setup":{"iram":{"0x30":1,"0x31":255,"0x32":2,"0x33":0,"0x34":3,"0x35":0,"0x36":238}},"expect":{"iram":{"0x36":0}}},{"setup":{"iram":{"0x30":1,"0x31":244,"0x32":1,"0x33":244,"0x34":1,"0x35":244,"0x36":238}},"expect":{"iram":{"0x36":2}}},{"setup":{"iram":{"0x30":2,"0x31":255,"0x32":2,"0x33":0,"0x34":3,"0x35":0,"0x36":238}},"expect":{"iram":{"0x36":1}}}]},"hints":["Code mẫu đã so số đếm với L1 bằng phép trừ 16 bit (byte thấp trước, rồi byte cao với SUBB nhận cờ mượn); C = 1 sau byte cao nghĩa là số đếm &lt; L1.","Làm lại đúng phép so đó với L2 (35H, 34H): nhớ CLR C trước byte thấp.","Mức 2 chỉ xét khi đã ≥ L1; không nhỏ hơn L2 thì tăng mức thêm 1."],"why":"Thêm yêu cầu tốt nhất là thêm một phép so giống hệt phép đã kiểm, không viết lại. So sánh phải 16 bit với số mượn: bộ thử 6 (01FFH với 0200H) và 8 (02FFH với 0300H) bắt lỗi chỉ so byte thấp; bộ thử 3, 4, 7 kiểm “bằng ngưỡng”."},{"t":"Hiển thị 0–255 tắt số 0 đầu ≤ 42 chu kỳ","d":"<p>Yêu cầu mới: hiển thị giá trị 0–255 ở <code>30H<\/code> trên 3 LED 7 đoạn anode chung và <b>tắt các số 0 đứng đầu<\/b>. Ghi mã đoạn của chữ số hàng trăm, chục, đơn vị vào <code>31H<\/code>, <code>32H<\/code>, <code>33H<\/code> (bảng mã như Bài 58: C0, F9, A4, B0, 99, 92, 82, F8, 80, 90). Chữ số tắt có mã <code>FFH<\/code>. Hàng trăm tắt khi bằng 0; hàng chục tắt khi cả trăm và chục bằng 0; hàng đơn vị luôn hiện. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: 205 → A4H, C0H, 92H; 7 → FFH, FFH, F8H. Đoạn này chạy mỗi lần số đếm đổi nên phải rẻ: không quá <b>42 chu kỳ máy<\/b> với mọi bộ thử (tính cả một lần <code>SJMP $<\/code>) và không quá <b>60 byte<\/b> mã (kể cả bảng).<\/p>","start":"        ORG     0000H\n        MOV     A,30H\n        MOV     R2,#0                   ; trăm\nTRAM:   CLR     C\n        SUBB    A,#100\n        JC      HETTRAM\n        INC     R2\n        SJMP    TRAM\nHETTRAM: ADD    A,#100\n        MOV     R3,#0                   ; chục\nCHUC:   CLR     C\n        SUBB    A,#10\n        JC      HETCHUC\n        INC     R3\n        SJMP    CHUC\nHETCHUC: ADD    A,#10                   ; A = đơn vị\n        MOV     DPTR,#MA7\n        MOVC    A,@A+DPTR\n        MOV     33H,A\n        MOV     A,R3\n        MOVC    A,@A+DPTR\n        MOV     32H,A\n        MOV     A,R2\n        MOVC    A,@A+DPTR\n        MOV     31H,A\n        SJMP    $\nMA7:    DB      0C0H,0F9H,0A4H,0B0H,99H ; 0–4, anode chung\n        DB      92H,82H,0F8H,80H,90H    ; 5–9\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":205,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x31":164,"0x32":192,"0x33":146}}},{"setup":{"iram":{"0x30":0,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x31":255,"0x32":255,"0x33":192}}},{"setup":{"iram":{"0x30":7,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x31":255,"0x32":255,"0x33":248}}},{"setup":{"iram":{"0x30":10,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x31":255,"0x32":249,"0x33":192}}},{"setup":{"iram":{"0x30":100,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x31":249,"0x32":192,"0x33":192}}},{"setup":{"iram":{"0x30":255,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x31":164,"0x32":146,"0x33":146}}},{"setup":{"iram":{"0x30":99,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x31":255,"0x32":144,"0x33":144}}}],"maxCyc":42,"maxBytes":60},"hints":["Code mẫu tách chữ số bằng trừ lặp (thời gian phụ thuộc giá trị) và chưa tắt số 0 đầu. DIV AB chia A cho B trong 4 chu kỳ: chia 100 lấy hàng trăm, phần dư (B) chia 10 lấy chục và đơn vị.","Ghi FFH vào 31H và 32H trước, rồi chỉ ghi đè bằng mã thật khi chữ số đó phải hiện.","Hàng trăm khác 0 thì hàng chục luôn hiện (kể cả 0, ví dụ 205). Chỉ dùng một lệnh SJMP $ ở cuối; các nhánh nhảy tới đó."],"why":"Thay đổi yêu cầu nhỏ (tắt số 0 đầu) nhưng phải giữ chỉ tiêu thời gian đã công bố. DIV AB cho thời gian gần như cố định (lời giải 34–40 chu kỳ, 55 byte), còn trừ lặp của code mẫu tốn 28 chu kỳ với 0 nhưng 77 chu kỳ với 255 và 91 chu kỳ với 99 (tính cả SJMP $). Bộ thử 5 (100) bắt lỗi tắt cả số 0 ở giữa/cuối; bộ thử 2 (0) kiểm hàng đơn vị luôn hiện."}]);

makeQuiz("quiz60","score60",[{"q": "Hồ sơ ghi tổng kiểm bản build 0CF9H. Bản trong chip có tổng 0CFBH. Kết luận nào đúng?", "o": ["Không sao, chênh lệch 2 là sai số", "Tổng kiểm chỉ để trang trí hồ sơ", "Chip bị hỏng phần cứng", "Chip không chứa đúng bản đã nghiệm thu; phải nạp lại bản đúng hoặc nghiệm thu lại bản mới"], "a": 3, "e": "Tổng kiểm nhận dạng bản build; khác tổng nghĩa là mã máy khác (dù chỉ một byte). Bằng chứng nghiệm thu chỉ đúng cho bản có tổng đã ghi."}, {"q": "Đổi thạch anh từ 12 MHz sang 11,0592 MHz. Tick 1 ms bằng Timer 0 chế độ 1 cần giá trị nạp nào?", "o": ["FC18H (giữ nguyên)", "FC00H", "FD00H", "FC66H (65 536 − 922)"], "a": 3, "e": "1 ms / (12 / 11,0592 MHz) = 921,6 chu kỳ, làm tròn 922; 65 536 − 922 = 64 614 = FC66H; tick thật ≈ 1 000,43 µs. Giữ FC18H thì tick dài 1 085 µs (ví dụ 3)."}, {"q": "Hỏi khi bảo vệ: “Vì sao không dùng ngắt cho bàn phím?” Câu trả lời nào tốt nhất?", "o": ["Quét phím trong tick tốn 120 chu kỳ (bảng ngân sách), tổng vẫn dưới 700; một lần bấm phím dài hơn nhiều lần chu kỳ quét 4 ms", "Vì em thấy thăm dò dễ hơn", "Vì ngắt luôn chậm hơn thăm dò", "Vì 8051 không có ngắt cho bàn phím"], "a": 0, "e": "Câu trả lời tốt dẫn số đo trong hồ sơ và nêu đánh đổi. Các câu khác là cảm nhận hoặc sai sự thật."}, {"q": "Chương trình dùng MOV R0,#90H rồi MOV A,@R0 chạy đúng trên AT89S52. Mang sang 8051 gốc thì sao?", "o": ["Đọc được SFR P1 ở địa chỉ 90H", "Trình dịch Keil báo lỗi", "8051 gốc không có RAM gián tiếp 80H–FFH; A nhận giá trị không xác định và chip không báo lỗi", "Chạy giống hệt vì cùng tập lệnh"], "a": 2, "e": "@R0 với địa chỉ ≥ 80H là RAM cao, chỉ có trên 8052/AT89S52; SFR chỉ truy cập trực tiếp. Mã máy giống nhau, nên trình dịch không phát hiện; trình mô phỏng ở cấu hình 128 byte báo lỗi để thấy (ví dụ 5)."}, {"q": "Thêm trạng thái mới vào máy trạng thái bảng (chỉ số = 4 × TT + SK). Việc nào dễ bị quên nhất và hậu quả là gì?", "o": ["Đổi tên nhãn; nếu quên thì trình dịch báo lỗi", "Thêm hàng mới vào bảng NEXT; nếu quên, MOVC đọc byte phía sau bảng và máy chuyển sai mà không báo lỗi", "Tăng SP; nếu quên thì ngăn xếp tràn", "Xóa cờ TF0; nếu quên thì tick nhanh"], "a": 1, "e": "Bảng không tự kiểm biên: thiếu hàng thì chỉ số rơi vào dữ liệu khác. Chạy lại bộ thử có vết trạng thái và thêm kiểm phạm vi (Bài 59) để bắt lỗi này."}]);

